DECLARE
  v_price products.price%TYPE;
BEGIN
  SELECT price INTO v_price FROM products WHERE id = 999;
  v_price := v_price * 0.9;  -- 10% off
  DBMS_OUTPUT.PUT_LINE('sale price: ' || v_price);
EXCEPTION
  WHEN NO_DATA_FOUND THEN
    DBMS_OUTPUT.PUT_LINE('sale price: 0');
END;
